import { ProductImage } from '../../shared/product-image.js';
import { Icon } from '../../shared/icons.js';
import {
	BLOCK_NAME, BLOCK_TITLE, BLOCK_DESC, attrsOf, newAttrs, templateOf, pagesOf, seedPages, seedTemplates, findBlock, walk,
	currentViewerBlocks, replacesGallery, insertBlock, removeBlock, moveBlock, mapBlocks, nextBlockId, ASPECTS, WIDTHS, CONTROL_KEYS, shortcodeFor,
} from '../../shared/block.js';
import { ViewerBlock } from '../store/block-theme.js';
import { priceHtml } from '../store/shop.js';
import { ProductSearch, variationOptions, variationLabel } from './block-controls.js';
import { protoLabel } from '../../shared/slots.js';

