function WpIcon({ name, size = 24 }) {
	if (name === 'cube') return html`<${Icon} name="php-box" size=${size} />`;
	return html`<svg class="wpse-ico" width=${size} height=${size} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d=${PATHS[name] || PATHS.group} /></svg>`;
}

// ── Block types ────────────────────────────────────────────────────────────

const TYPES = {
	'core/template-part': { title: (a) => (a?.slug === 'footer' ? 'Footer' : 'Header'), icon: 'part', desc: 'Edit the different global regions of your site, like the header, footer, sidebar, or create your own.' },
	'woocommerce/breadcrumbs': { title: 'Store Breadcrumbs', icon: 'crumbs', desc: 'Enable customers to keep track of their location within the store and navigate back to parent pages.' },
	'woocommerce/store-notices': { title: 'Store Notices', icon: 'notice', desc: 'Display shopper-facing notifications generated by WooCommerce.' },
	'core/columns': { title: 'Columns', icon: 'columns', desc: 'Display content in multiple columns, with blocks added to each column.' },
	'core/column': { title: 'Column', icon: 'column', desc: 'A single column within a columns block.' },
	'woocommerce/product-image-gallery': { title: 'Product Image Gallery', icon: 'gallery', desc: "Display a product's images." },
	'core/post-title': { title: 'Title', icon: 'title', desc: 'Displays the title of a post, page, or any other content-type.' },
	'woocommerce/product-price': { title: 'Product Price', icon: 'price', desc: 'Display the price of a product.' },
	'core/post-excerpt': { title: 'Excerpt', icon: 'excerpt', desc: 'Display the excerpt.' },
	'woocommerce/add-to-cart-form': { title: 'Add to Cart with Options', icon: 'cart', desc: 'Display a button that lets customers add a product to their cart.' },
	'woocommerce/product-meta': { title: 'Product Meta', icon: 'meta', desc: "Display a product's SKU, categories, tags, and more." },
	'woocommerce/product-details': { title: 'Product Details', icon: 'details', desc: "Display a product's description, attributes, and reviews." },
	'woocommerce/related-products': { title: 'Related Products', icon: 'related', desc: 'Display related products.' },
	'core/paragraph': { title: 'Paragraph', icon: 'paragraph', desc: 'Start with the basic building block of all narrative.' },
	'core/heading': { title: 'Heading', icon: 'heading', desc: 'Introduce new sections and organize content to help visitors understand the structure of your content.' },
	[BLOCK_NAME]: { title: BLOCK_TITLE, icon: 'cube', desc: BLOCK_DESC },
};
const typeOf = (bl) => TYPES[bl?.name] || { title: bl?.name || 'Block', icon: 'group', desc: '' };
const titleOf = (bl) => (typeof typeOf(bl).title === 'function' ? typeOf(bl).title(bl.attrs) : typeOf(bl).title);

const KEYWORDS = ['3d', 'model', 'viewer', 'ar', 'glb', 'product', 'customizer', 'woocommerce'];
const INSERTER = [
	['Text', [['Paragraph', 'paragraph'], ['Heading', 'heading'], ['List', 'list2'], ['Quote', 'quote']]],
	['Media', [['Image', 'image'], ['Gallery', 'gallery'], ['Video', 'video'], ['Cover', 'cover']]],
	['Design', [['Group', 'group'], ['Columns', 'columns'], ['Spacer', 'spacer'], ['Separator', 'separator']]],
	['WooCommerce', [['Product Price', 'price'], ['Add to Cart with Options', 'cart'], ['Product Image Gallery', 'gallery'], ['Product Meta', 'meta'], [BLOCK_TITLE, 'cube', BLOCK_NAME]]],
];

// ── Editor state (local; Save writes the template/page) ────────────────────

function docFor(state, params) {
	if (params?.[0] === 'page') {
		const page = pagesOf(state)[params[1]];
		if (page && page.builder === 'blocks') return { kind: 'page', id: page.id, title: page.title, slug: page.slug, blocks: page.blocks || [] };
	}
	const t = templateOf(state);
	return { kind: 'template', id: 'single-product', title: t.title, slug: t.slug, blocks: t.blocks };
}

function useEditorDoc(params) {
	const state = useStore();
	const saved = docFor(state, params);
	const [blocks, setBlocks] = useState(saved.blocks);
	const [past, setPast] = useState([]);
	const [future, setFuture] = useState([]);
	const update = (fn) => {
		setPast((p) => [...p.slice(-49), blocks]);
		setFuture([]);
		setBlocks(fn(blocks));
	};
	const undo = () => {
		if (!past.length) return;
		setFuture((f) => [blocks, ...f]);
		setBlocks(past[past.length - 1]);
		setPast((p) => p.slice(0, -1));
	};
	const redo = () => {
		if (!future.length) return;
		setPast((p) => [...p, blocks]);
		setBlocks(future[0]);
		setFuture((f) => f.slice(1));
	};
	const dirty = JSON.stringify(blocks) !== JSON.stringify(saved.blocks);
	const save = () => {
		if (saved.kind === 'template') store.patch('wpTemplates', (old) => ({ ...(old || seedTemplates()), 'single-product': { ...templateOf(store.get()), blocks } }));
		else store.patch('wpPages', (old) => ({ ...(old || seedPages()), [saved.id]: { ...pagesOf(store.get())[saved.id], blocks } }));
	};
	return { doc: { ...saved, blocks }, saved, update, undo, redo, canUndo: past.length > 0, canRedo: future.length > 0, dirty, save };
}

const narrowNow = () => (typeof matchMedia === 'function' ? matchMedia('(max-width: 782px)').matches : false);

// ── Screen ─────────────────────────────────────────────────────────────────

export default function SiteEditor({ params }) {
	const on = useFeature('block');
	if (!on) {
		return html`<div class="wpse-flagoff">
			<p><strong>Turn on the Product viewer block feature</strong> to use the Site Editor.</p>
			<p>Turn on "Product viewer block" in <a href="#admin.settings.modules">WooCommerce → 3D Models → Settings → Features</a>.</p>
			<p><a href="#admin.models">Back to 3D Models</a></p>
		</div>`;
	}
	return html`<${Editor} params=${params} />`;
}

function Editor({ params }) {
	const state = useStore();
	const ed = useEditorDoc(params);
	const { doc } = ed;
	const isTemplate = doc.kind === 'template';
	const [selected, setSelected] = useState(null);
	const [left, setLeft] = useState(null); // 'inserter' | 'list' | null
	const [sidebar, setSidebar] = useState(() => !narrowNow());
	const [tab, setTab] = useState('doc');
	const [docMenu, setDocMenu] = useState(false);
	const [saving, setSaving] = useState(false);
	const [snack, setSnack] = useState('');
	const products = Object.values(state.products || {}).filter((p) => p.status === 'publish');
	const [previewId, setPreviewId] = useState(() => (products.find((p) => p.id === 101) || products[0])?.id || 0);
	const preview = state.products?.[previewId];
	const sel = selected ? findBlock(doc.blocks, selected)?.block : null;

	// A newly inserted block scrolls into view (WordPress does the same).
	const [reveal, setReveal] = useState(null);
	useEffect(() => {
		if (!reveal) return;
		const t = setTimeout(() => document.querySelector(`.wpse [data-block="${reveal}"]`)?.scrollIntoView({ block: 'center', behavior: 'smooth' }), 60);
		return () => clearTimeout(t);
	}, [reveal]);

	useEffect(() => {
		if (!snack) return;
		const t = setTimeout(() => setSnack(''), 6000);
		return () => clearTimeout(t);
	}, [snack]);

	useEffect(() => {
		const onKey = (e) => {
			if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z') {
				if (e.target.closest?.('input, textarea, select')) return;
				e.preventDefault();
				e.shiftKey ? ed.redo() : ed.undo();
			}
		};
		document.addEventListener('keydown', onKey);
		return () => document.removeEventListener('keydown', onKey);
	});

	const select = (id) => {
		setSelected(id);
		setTab(id ? 'block' : 'doc');
		setDocMenu(false);
	};

	const insertViewer = () => {
		const block = { id: nextBlockId(doc.blocks, 'b'), name: BLOCK_NAME, attrs: newAttrs({ productTemplate: isTemplate }) };
		const target = sel?.name === 'core/column' ? sel.id : null;
		ed.update((blocks) => (target ? mapBlocks(blocks, (bl) => (bl.id === target ? { ...bl, inner: [...(bl.inner || []), block] } : bl)) : insertBlock(blocks, block, selected)));
		setSelected(block.id);
		setReveal(block.id);
		setTab('block');
		if (narrowNow()) setLeft(null);
		else setLeft((l) => (l === 'inserter' ? null : l));
	};

	const setAttrs = (id, patch) => ed.update((blocks) => mapBlocks(blocks, (bl) => (bl.id === id ? { ...bl, attrs: { ...(bl.attrs || {}), ...patch } } : bl)));
	const remove = (id) => {
		ed.update((blocks) => removeBlock(blocks, id));
		select(null);
	};
	const duplicate = (id) => {
		const src = findBlock(doc.blocks, id)?.block;
		if (!src) return;
		const copy = { ...src, id: nextBlockId(doc.blocks, 'b'), attrs: { ...(src.attrs || {}) } };
		ed.update((blocks) => insertBlock(blocks, copy, id));
		select(copy.id);
		setReveal(copy.id);
	};

	const doSave = () => {
		setSaving(true);
		setTimeout(() => {
			ed.save();
			setSaving(false);
			setSnack(isTemplate ? 'Template updated.' : 'Page updated.');
		}, 500);
	};

	const viewUrl = isTemplate ? 'store.product.' + (preview?.slug || 'lounge-chair') : 'store.page.' + doc.slug;
	const view = () => {
		if (isTemplate) store.patch('demo.theme', 'block');
		go(viewUrl);
	};

	const docs = [{ key: 'template', label: 'Single Product', kind: 'Template', route: 'admin.site-editor' }, ...Object.values(pagesOf(state)).filter((p) => p.builder === 'blocks').map((p) => ({ key: 'page' + p.id, label: p.title, kind: 'Page', route: 'admin.site-editor.page.' + p.id }))];

	return html`
		<div class=${cx('wpse', left && 'has-left', sidebar && 'has-sidebar')}>
			<header class="wpse-top">
				<div class="wpse-top__start">
					<a class="wpse-site" href="#admin.models" aria-label="Back to 3D Models" title="Back to 3D Models"><${WpIcon} name="back" /></a>
					<button type="button" class=${cx('wpse-tbtn wpse-tbtn--primary', left === 'inserter' && 'is-pressed')} aria-pressed=${left === 'inserter'} aria-label="Block Inserter" title="Block Inserter" onClick=${() => setLeft(left === 'inserter' ? null : 'inserter')}>
						<${WpIcon} name=${left === 'inserter' ? 'close' : 'plus'} />
					</button>
					<button type="button" class="wpse-tbtn" aria-label="Undo" title="Undo" disabled=${!ed.canUndo} onClick=${ed.undo}><${WpIcon} name="undo" /></button>
					<button type="button" class="wpse-tbtn" aria-label="Redo" title="Redo" disabled=${!ed.canRedo} onClick=${ed.redo}><${WpIcon} name="redo" /></button>
					<button type="button" class=${cx('wpse-tbtn wpse-hide-sm', left === 'list' && 'is-pressed')} aria-pressed=${left === 'list'} aria-label="Document Overview" title="Document Overview" onClick=${() => setLeft(left === 'list' ? null : 'list')}><${WpIcon} name="list" /></button>
				</div>
				<div class="wpse-top__center">
					<button type="button" class="wpse-docbar" aria-expanded=${docMenu} onClick=${() => setDocMenu(!docMenu)}>
						<span class="wpse-docbar__title">${doc.title}</span>
						<span class="wpse-docbar__kind">· ${isTemplate ? 'Template' : 'Page'}</span>
						<${WpIcon} name="down" size=${18} />
					</button>
					${docMenu &&
					html`<div class="wpse-docmenu" role="menu">
						${docs.map((d) => html`<a key=${d.key} role="menuitem" href=${'#' + d.route} class=${cx('wpse-docmenu__item', (isTemplate ? d.key === 'template' : d.key === 'page' + doc.id) && 'is-current')} onClick=${() => setDocMenu(false)}>
							<span>${d.label}</span><span class="wpse-docmenu__kind">${d.kind}</span>
						</a>`)}
					</div>`}
				</div>
				<div class="wpse-top__end">
					${isTemplate &&
					html`<label class="wpse-preview wpse-hide-sm">
						<span>Preview</span>
						<select value=${previewId} onChange=${(e) => setPreviewId(Number(e.currentTarget.value))}>
							${products.map((p) => html`<option key=${p.id} value=${p.id}>${p.name}</option>`)}
						</select>
					</label>`}
					<button type="button" class="wpse-tbtn wpse-hide-sm" aria-label="View" title="View" onClick=${view}><${WpIcon} name="external" /></button>
					<button type="button" class="wpse-save" disabled=${!ed.dirty || saving} onClick=${doSave}>${saving ? 'Saving…' : ed.dirty ? 'Save' : 'Saved'}</button>
					<button type="button" class=${cx('wpse-tbtn', sidebar && 'is-pressed')} aria-pressed=${sidebar} aria-label="Settings" title="Settings" onClick=${() => setSidebar(!sidebar)}><${WpIcon} name="sidebar" /></button>
				</div>
			</header>
			<div class="wpse-body">
				${left === 'inserter' && html`<${Inserter} onInsert=${insertViewer} onClose=${() => setLeft(null)} />`}
				${left === 'list' && html`<${ListView} blocks=${doc.blocks} selected=${selected} onSelect=${select} onClose=${() => setLeft(null)} />`}
				<div class="wpse-canvas" onClick=${() => select(null)}>
					<div class=${cx('wpse-frame', isTemplate ? 'wpse-frame--template' : 'wpse-frame--page')}>
						${!isTemplate && html`<h1 class="wpse-page-title">${doc.title}</h1>`}
						<${Blocks}
							blocks=${doc.blocks}
							ctx=${{ state, isTemplate, preview, template: isTemplate ? { blocks: doc.blocks } : null, selected, select, move: (id, d) => ed.update((b) => moveBlock(b, id, d)), remove, duplicate, setAttrs }}
						/>
					</div>
				</div>
				${sidebar &&
				html`<${Sidebar}
					tab=${tab}
					setTab=${setTab}
					doc=${doc}
					block=${sel}
					preview=${preview}
					onAttrs=${(patch) => sel && setAttrs(sel.id, patch)}
					onClose=${() => setSidebar(false)}
					onView=${view}
				/>`}
			</div>
			${snack &&
			html`<div class="wpse-snack" role="status">
				${snack} <button type="button" class="wpse-snack__link" onClick=${view}>View ${isTemplate ? 'site' : 'page'}</button>
			</div>`}
		</div>
	`;
}

// ── Canvas ─────────────────────────────────────────────────────────────────

function Blocks({ blocks, ctx }) {
	return (blocks || []).map((bl, i) => html`<${EditorBlock} key=${bl.id} block=${bl} ctx=${ctx} first=${i === 0} last=${i === blocks.length - 1} />`);
}

function EditorBlock({ block: bl, ctx, first, last }) {
	const isSel = ctx.selected === bl.id;
	const container = bl.name === 'core/columns' || bl.name === 'core/column';
	const click = (e) => {
		e.stopPropagation();
		if (!isSel) ctx.select(bl.id);
	};
	return html`<div
		class=${cx('wpse-block', 'wpse-block--' + bl.name.replace('/', '-'), isSel && 'is-selected', container && 'is-container')}
		data-block=${bl.id}
		data-type=${bl.name}
		onClick=${click}
	>
		${isSel && html`<${BlockToolbar} block=${bl} ctx=${ctx} first=${first} last=${last} />`}
		<${BlockPreview} block=${bl} ctx=${ctx} selected=${isSel} />
	</div>`;
}

function BlockToolbar({ block: bl, ctx, first, last }) {
	const [menu, setMenu] = useState(false);
	const ours = bl.name === BLOCK_NAME;
	const a = attrsOf(bl);
	const aligns = [['', 'alignNone', 'None'], ['center', 'alignCenter', 'Align center'], ['wide', 'alignWide', 'Wide width'], ['full', 'alignFull', 'Full width']];
	const [alignOpen, setAlignOpen] = useState(false);
	const cur = aligns.find(([v]) => v === a.align) || aligns[0];
	return html`<div class="wpse-toolbar" role="toolbar" aria-label="Block tools" onClick=${(e) => e.stopPropagation()}>
		<span class="wpse-toolbar__type" title=${titleOf(bl)}><${WpIcon} name=${typeOf(bl).icon} size=${20} /></span>
		<span class="wpse-toolbar__sep"></span>
		<button type="button" class="wpse-tool" aria-label="Move up" title="Move up" disabled=${first} onClick=${() => ctx.move(bl.id, -1)}><${WpIcon} name="up" size=${20} /></button>
		<button type="button" class="wpse-tool" aria-label="Move down" title="Move down" disabled=${last} onClick=${() => ctx.move(bl.id, 1)}><${WpIcon} name="down" size=${20} /></button>
		${ours &&
		!ctx.isTemplate &&
		html`<span class="wpse-toolbar__sep"></span>
			<span class="wpse-toolbar__drop">
				<button type="button" class="wpse-tool" aria-label="Align" title="Align" aria-expanded=${alignOpen} onClick=${() => setAlignOpen(!alignOpen)}><${WpIcon} name=${cur[1]} size=${20} /></button>
				${alignOpen &&
				html`<div class="wpse-popover" role="menu">
					${aligns.map(([v, icon, label]) => html`<button key=${label} type="button" role="menuitemradio" aria-checked=${a.align === v} class=${cx('wpse-popover__item', a.align === v && 'is-active')} onClick=${() => (ctx.setAttrs(bl.id, { align: v }), setAlignOpen(false))}>
						<${WpIcon} name=${icon} size=${20} /> ${label}
					</button>`)}
				</div>`}
			</span>`}
		${ours &&
		html`<span class="wpse-toolbar__sep"></span>
			<span class="wpse-toolbar__drop">
				<button type="button" class="wpse-tool" aria-label="Options" title="Options" aria-expanded=${menu} onClick=${() => setMenu(!menu)}><${WpIcon} name="more" size=${20} /></button>
				${menu &&
				html`<div class="wpse-popover wpse-popover--end" role="menu">
					<button type="button" role="menuitem" class="wpse-popover__item" onClick=${() => (setMenu(false), ctx.duplicate(bl.id))}><${WpIcon} name="copy" size=${20} /> Duplicate</button>
					<button type="button" role="menuitem" class="wpse-popover__item is-danger" onClick=${() => (setMenu(false), ctx.remove(bl.id))}><${WpIcon} name="trash" size=${20} /> Delete</button>
				</div>`}
			</span>`}
	</div>`;
}

function BlockPreview({ block: bl, ctx, selected }) {
	const { state, preview: p } = ctx;
	const a = bl.attrs || {};
	switch (bl.name) {
		case 'core/template-part':
			return a.slug === 'footer'
				? html`<div class="wpse-tp wpse-tp--footer"><strong>Demo Store</strong><span>Shop · Cart · Checkout</span><span class="wpse-muted">© 2026 Demo Store.</span></div>`
				: html`<div class="wpse-tp wpse-tp--header"><strong>Demo Store</strong><span>Shop</span><span>Cart</span><span>Checkout</span><span class="wpse-tp__cart">$0.00</span></div>`;
		case 'woocommerce/breadcrumbs':
			return html`<div class="wpse-crumbs">Home / ${p?.category || 'Category'} / ${p?.name || 'Product'}</div>`;
		case 'woocommerce/store-notices':
			return html`<div class="wpse-notices">Store notices</div>`;
		case 'core/columns':
			return html`<div class="wpse-columns"><${Blocks} blocks=${bl.inner} ctx=${ctx} /></div>`;
		case 'core/column':
			return html`<div class="wpse-column"><${Blocks} blocks=${bl.inner} ctx=${ctx} /></div>`;
		case 'woocommerce/product-image-gallery': {
			const hidden = ctx.template && replacesGallery(ctx.template) && p && is3DAvailable(state, p.id);
			return html`<div class=${cx('wpse-gallery', hidden && 'is-hidden-by-viewer')}>
				${p && html`<${ProductImage} product=${p} size=${520} fluid class="wpse-gallery__main" alt="" />`}
				<div class="wpse-gallery__thumbs">${[0, 1, 2].map((i) => html`<span key=${i} class="wpse-gallery__thumb"></span>`)}</div>
				${hidden && html`<p class="wpse-gallery__note">Hidden on the storefront: the 3D Product Viewer block replaces the gallery for products with a 3D model.</p>`}
			</div>`;
		}
		case 'core/post-title':
			return html`<h1 class="wpse-ptitle">${p?.name || 'Product title'}</h1>`;
		case 'woocommerce/product-price':
			return html`<p class="wpse-price">${p ? priceHtml(state, p) : '$0.00'}</p>`;
		case 'core/post-excerpt':
			return html`<p class="wpse-excerpt">${p?.short || 'Product excerpt.'}</p>`;
		case 'woocommerce/add-to-cart-form':
			return html`<div class="wpse-atc">
				${p?.type === 'variable' && p.attributes.map((at) => html`<div key=${at.name} class="wpse-atc__row"><span>${at.name}</span><span class="wpse-atc__select">Choose an option</span></div>`)}
				<div class="wpse-atc__row"><span class="wpse-atc__qty">1</span><span class="wpse-atc__btn">Add to cart</span></div>
			</div>`;
		case 'woocommerce/product-meta':
			return html`<div class="wpse-meta">SKU: ${p?.sku || 'N/A'}<br />Category: ${p?.category || ''}</div>`;
		case 'woocommerce/product-details':
			return html`<div class="wpse-details">
				<div class="wpse-details__tabs"><span class="is-on">Description</span><span>Additional information</span><span>Reviews (0)</span></div>
				<p>${p?.description || 'Product description.'}</p>
			</div>`;
		case 'woocommerce/related-products': {
			const rel = Object.values(state.products || {}).filter((x) => x.status === 'publish' && x.id !== p?.id).slice(0, 4);
			return html`<div class="wpse-related">
				<h2>Related products</h2>
				<div class="wpse-related__grid">${rel.map((x) => html`<div key=${x.id} class="wpse-related__card"><${ProductImage} product=${x} size=${200} fluid alt="" /><span>${x.name}</span></div>`)}</div>
			</div>`;
		}
		case 'core/paragraph':
			return html`<p class="wpse-p">${a.content}</p>`;
		case 'core/heading':
			return html`<h2 class="wpse-h">${a.content}</h2>`;
		case BLOCK_NAME:
			return html`<${ViewerPreview} block=${bl} ctx=${ctx} selected=${selected} />`;
		default:
			return html`<div class="wpse-unknown">${bl.name}</div>`;
	}
}

/** The viewer block in the canvas: live viewer, or a placeholder (no product / no 3D). */
function ViewerPreview({ block: bl, ctx, selected }) {
	const { state, preview, isTemplate } = ctx;
	const a = attrsOf(bl);
	const current = !Number(a.productId);
	const pid = current ? (isTemplate ? preview?.id : 0) : Number(a.productId);
	const product = pid ? state.products?.[pid] : null;
	const placeholder = html`<div class="wpse-ph">
		<div class="wpse-ph__label"><${WpIcon} name="cube" size=${20} /> ${BLOCK_TITLE}</div>
		${!product
			? html`<p>Choose a product to show its 3D model.</p>
				<button type="button" class="wpse-ph__btn" onClick=${(e) => (e.stopPropagation(), ctx.select(bl.id))}>Choose a product</button>`
			: html`<p>${product.name} has no 3D model. Turn on 3D on its 3D Model tab.</p>
				<a class="wpse-ph__btn" href=${'#admin.product.' + product.id} onClick=${(e) => e.stopPropagation()}>Edit product</a>`}
	</div>`;
	return html`<div class=${cx('wpse-viewer', !selected && 'is-locked')}>
		<${ViewerBlock} attrs=${a} productId=${pid} current=${current && isTemplate} editor=${true} placeholder=${placeholder} />
		${!selected && product && is3DAvailable(state, pid) && html`<div class="wpse-viewer__shield" aria-hidden="true"></div>`}
	</div>`;
}

// ── Left panels ────────────────────────────────────────────────────────────

function Inserter({ onInsert, onClose }) {
	const [q, setQ] = useState('');
	const [note, setNote] = useState('');
	const needle = q.trim().toLowerCase();
	const ref = useRef(null);
	useEffect(() => ref.current?.focus(), []);
	// Every word must start a keyword ("3d viewer" yes; "cart" must not hit "ar").
	const match = (label, name) => !needle || label.toLowerCase().includes(needle) || (name === BLOCK_NAME && needle.split(/\s+/).every((w) => KEYWORDS.some((k) => k.startsWith(w))));
	const cats = INSERTER.map(([cat, items]) => [cat, items.filter(([label, , name]) => match(label, name))]).filter(([, items]) => items.length);
	return html`<aside class="wpse-left wpse-inserter" aria-label="Block Library">
		<div class="wpse-left__head">
			<div class="wpse-tabs"><span class="wpse-tabs__tab is-on">Blocks</span><span class="wpse-tabs__tab">Patterns</span><span class="wpse-tabs__tab">Media</span></div>
			<button type="button" class="wpse-tbtn" aria-label="Close Block Inserter" onClick=${onClose}><${WpIcon} name="close" /></button>
		</div>
		<div class="wpse-search">
			<input ref=${ref} type="search" placeholder="Search" aria-label="Search" value=${q} onInput=${(e) => setQ(e.currentTarget.value)} />
			<${WpIcon} name="search" size=${20} />
		</div>
		<div class="wpse-left__body">
			${cats.length === 0 && html`<p class="wpse-muted wpse-pad">No results found.</p>`}
			${cats.map(
				([cat, items]) => html`<div key=${cat} class="wpse-cat">
					<h2 class="wpse-cat__title">${cat}</h2>
					<div class="wpse-cat__grid">
						${items.map(([label, icon, name]) =>
							name === BLOCK_NAME
								? html`<button key=${label} type="button" class="wpse-item is-ours" title=${BLOCK_DESC} onClick=${onInsert}><span class="wpse-item__icon"><${WpIcon} name="cube" /></span><span class="wpse-item__label">${label}</span></button>`
								: html`<button key=${label} type="button" class="wpse-item is-inert" aria-disabled="true" title=${`Not part of the ${protoLabel().toLowerCase()}`} onClick=${() => setNote(label)}><span class="wpse-item__icon"><${WpIcon} name=${icon} /></span><span class="wpse-item__label">${label}</span></button>`
						)}
					</div>
				</div>`
			)}
			${note && html`<p class="wpse-muted wpse-pad">${note} is not part of the ${protoLabel().toLowerCase()}. Only ${BLOCK_TITLE} can be added.</p>`}
		</div>
	</aside>`;
}

function ListView({ blocks, selected, onSelect, onClose }) {
	const rows = [];
	walk(blocks, (bl, at) => {
		let depth = 0;
		for (let p = at.parent; p; p = findBlock(blocks, p.id)?.parent) depth++;
		rows.push([bl, depth]);
	});
	return html`<aside class="wpse-left wpse-listview" aria-label="Document Overview">
		<div class="wpse-left__head">
			<div class="wpse-tabs"><span class="wpse-tabs__tab is-on">List View</span><span class="wpse-tabs__tab">Outline</span></div>
			<button type="button" class="wpse-tbtn" aria-label="Close" onClick=${onClose}><${WpIcon} name="close" /></button>
		</div>
		<ul class="wpse-left__body wpse-tree" role="tree">
			${rows.map(
				([bl, depth]) => html`<li key=${bl.id} role="treeitem" aria-selected=${selected === bl.id}>
					<button type="button" class=${cx('wpse-tree__row', selected === bl.id && 'is-selected', bl.name === BLOCK_NAME && 'is-ours')} style=${{ paddingLeft: 8 + depth * 16 + 'px' }} onClick=${() => onSelect(bl.id)}>
						<${WpIcon} name=${typeOf(bl).icon} size=${20} /> <span>${titleOf(bl)}</span>
					</button>
				</li>`
			)}
		</ul>
	</aside>`;
}

// ── Settings sidebar ───────────────────────────────────────────────────────

function Sidebar({ tab, setTab, doc, block, preview, onAttrs, onClose, onView }) {
	const isTemplate = doc.kind === 'template';
	const cur = block ? tab : 'doc';
	return html`<aside class="wpse-sidebar" aria-label="Settings">
		<div class="wpse-sidebar__head">
			<div class="wpse-tabs" role="tablist">
				<button type="button" role="tab" aria-selected=${cur === 'doc'} class=${cx('wpse-tabs__tab', cur === 'doc' && 'is-on')} onClick=${() => setTab('doc')}>${isTemplate ? 'Template' : 'Page'}</button>
				<button type="button" role="tab" aria-selected=${cur === 'block'} class=${cx('wpse-tabs__tab', cur === 'block' && 'is-on')} disabled=${!block} onClick=${() => setTab('block')}>Block</button>
			</div>
			<button type="button" class="wpse-tbtn" aria-label="Close Settings" onClick=${onClose}><${WpIcon} name="close" /></button>
		</div>
		<div class="wpse-sidebar__body">
			${cur === 'doc' ? html`<${DocPanel} doc=${doc} onView=${onView} />` : block?.name === BLOCK_NAME ? html`<${ViewerInspector} key=${block.id} block=${block} isTemplate=${isTemplate} preview=${preview} onAttrs=${onAttrs} />` : html`<${OtherInspector} block=${block} />`}
		</div>
	</aside>`;
}

function Card({ icon, title, desc }) {
	return html`<div class="wpse-card"><span class="wpse-card__icon"><${WpIcon} name=${icon} /></span><div><h2 class="wpse-card__title">${title}</h2><p class="wpse-card__desc">${desc}</p></div></div>`;
}

function Panel({ title, open: initial = true, class: extra, children }) {
	const [open, setOpen] = useState(initial);
	return html`<div class=${cx('wpse-panel', open && 'is-opened', extra)}>
		<h2 class="wpse-panel__title"><button type="button" aria-expanded=${open} onClick=${() => setOpen(!open)}>${title}<${WpIcon} name=${open ? 'up' : 'down'} size=${20} /></button></h2>
		${open && html`<div class="wpse-panel__body">${children}</div>`}
	</div>`;
}

function DocPanel({ doc, onView }) {
	const state = useStore();
	const theme = state.demo?.theme || 'classic';
	if (doc.kind === 'page') {
		const viewers = [];
		walk(doc.blocks, (bl) => bl.name === BLOCK_NAME && viewers.push(bl));
		return html`
			<${Card} icon="excerpt" title=${doc.title} desc="Page" />
			<${Panel} title="Summary">
				<dl class="wpse-dl"><dt>Status</dt><dd>Published</dd><dt>Link</dt><dd><button type="button" class="wpse-link" onClick=${onView}>/${doc.slug}/</button></dd></dl>
			</${Panel}>
			<${Panel} title="3D viewers" class="proto-only">
				<p class="wpse-help">${viewers.length ? `${viewers.length} 3D Product Viewer ${viewers.length === 1 ? 'block' : 'blocks'} on this page.` : 'No 3D Product Viewer block on this page yet.'}</p>
			</${Panel}>
		`;
	}
	const uses = currentViewerBlocks(doc).length > 0;
	const positionLabel = POSITIONS[state.settings?.position] || POSITIONS.replace_image;
	return html`
		<${Card} icon="part" title="Single Product" desc="Displays a single product." />
		<${Panel} title="3D viewer" class="proto-only">
			${uses
				? html`<p class="wpse-help">The 3D Product Viewer block places the viewer on this template. The product's own placement is turned off here.</p>`
				: html`<p class="wpse-help">Products use their own placement (3D Models → Settings → Placement). Default: ${positionLabel}.</p>
					<p class="wpse-help">Add the 3D Product Viewer block to choose where the viewer goes.</p>`}
		</${Panel}>
		${theme !== 'block' &&
		html`<div class="proto-cart-hint wpse-hint"><span class="proto-cart-hint__tag">${protoLabel()}</span><span>The demo storefront uses the classic theme. <button type="button" class="wpse-link" onClick=${() => store.patch('demo.theme', 'block')}>Use the block theme</button> to see this template on the product page.</span></div>`}
	`;
}

function OtherInspector({ block }) {
	const t = typeOf(block);
	return html`<${Card} icon=${t.icon} title=${titleOf(block)} desc=${t.desc} />
		<p class="wpse-help wpse-pad">This block's settings are not part of the ${protoLabel().toLowerCase()}.</p>`;
}

// ── 3D Product Viewer inspector ────────────────────────────────────────────

const uid = (() => {
	let n = 0;
	return (p) => p + '-' + ++n;
})();

function Radio({ name, value, options, onChange }) {
	return html`<div class="wpse-radios" role="radiogroup">
		${options.map(([v, label, disabled]) => {
			const id = name + '-' + v;
			return html`<div key=${v} class=${cx('wpse-radio', disabled && 'is-disabled')}>
				<input id=${id} type="radio" name=${name} checked=${value === v} disabled=${disabled} onChange=${() => onChange(v)} />
				<label for=${id}>${label}</label>
			</div>`;
		})}
	</div>`;
}

function Toggle({ label, checked, onChange, help }) {
	const [id] = useState(() => uid('wpse-toggle'));
	return html`<div class="wpse-control">
		<div class="wpse-toggle">
			<span class=${cx('wpse-toggle__track', checked && 'is-checked')}>
				<input id=${id} type="checkbox" class="wpse-toggle__input" checked=${checked} onChange=${(e) => onChange(e.currentTarget.checked)} />
				<span class="wpse-toggle__thumb"></span>
			</span>
			<label for=${id}>${label}</label>
		</div>
		${help && html`<p class="wpse-help">${help}</p>`}
	</div>`;
}

function Select({ label, value, options, onChange, disabled, help }) {
	const [id] = useState(() => uid('wpse-select'));
	return html`<div class="wpse-control">
		<label class="wpse-label" for=${id}>${label}</label>
		<select id=${id} class="wpse-input" value=${value} disabled=${disabled} onChange=${(e) => onChange(e.currentTarget.value)}>
			${options.map(([v, l]) => html`<option key=${v} value=${v}>${l}</option>`)}
		</select>
		${help && html`<p class="wpse-help">${help}</p>`}
	</div>`;
}

function ViewerInspector({ block, isTemplate, preview, onAttrs }) {
	const state = useStore();
	const a = attrsOf(block);
	const current = !Number(a.productId);
	const pid = current ? (isTemplate ? preview?.id : 0) : Number(a.productId);
	const product = pid ? state.products?.[pid] : null;
	const name = 'wpse-' + block.id;
	const [copied, setCopied] = useState(false);
	const settings = product ? viewerSettingsFor(state, product.id) : null;
	const vOpts = current ? [] : variationOptions(state, pid);
	const sc = shortcodeFor(a, pid > 0 ? pid : 0);
	const timer = useRef(0);
	useEffect(() => () => clearTimeout(timer.current), []);
	const done = () => {
		setCopied(true);
		clearTimeout(timer.current);
		timer.current = setTimeout(() => setCopied(false), 1800);
	};
	// Same as Settings → Shortcodes: Clipboard API, else a hidden textarea + execCommand.
	const fallback = () => {
		let ok = false;
		try {
			const ta = document.createElement('textarea');
			ta.value = sc;
			ta.setAttribute('readonly', '');
			ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0';
			document.body.appendChild(ta);
			ta.select();
			ok = document.execCommand('copy');
			ta.remove();
		} catch {
			ok = false;
		}
		return ok;
	};
	const copy = () => {
		try {
			if (window.isSecureContext && navigator.clipboard?.writeText) navigator.clipboard.writeText(sc).then(done, () => fallback() && done());
			else if (fallback()) done();
		} catch {
			if (fallback()) done();
		}
	};
	return html`
		<${Card} icon="cube" title=${BLOCK_TITLE} desc=${BLOCK_DESC} />
		<${Panel} title="Product">
			<${Radio}
				name=${name + '-src'}
				value=${current ? 'current' : 'pick'}
				options=${[['current', 'Current product', !isTemplate], ['pick', 'Choose a product']]}
				onChange=${(v) => onAttrs({ productId: v === 'current' ? 0 : -1, variationId: 0 })}
			/>
			${!isTemplate && html`<p class="wpse-help">Current product works in product templates only.</p>`}
			${!current && html`<${ProductSearch} value=${Number(a.productId) > 0 ? Number(a.productId) : 0} onChange=${(id) => onAttrs({ productId: id, variationId: 0 })} />`}
			${current
				? product?.type === 'variable' && html`<${Select} label="Variation" value="0" options=${[[0, 'Follow the variation form']]} disabled=${true} help="Follows the variation the shopper picks." />`
				: vOpts.length > 0 && html`<${Select} label="Variation" value=${String(a.variationId || 0)} options=${vOpts} onChange=${(v) => onAttrs({ variationId: Number(v) })} />`}
		</${Panel}>
		${isTemplate &&
		current &&
		html`<${Panel} title="Placement">
			<${Radio}
				name=${name + '-place'}
				value=${a.placement}
				options=${[['gallery', 'Replace the product gallery'], ['standalone', 'Next to the gallery']]}
				onChange=${(v) => onAttrs({ placement: v })}
			/>
			<p class="wpse-help">The product's own placement is turned off on this template.${settings ? ` (${preview.name}: ${POSITIONS[settings.position]})` : ''}</p>
		</${Panel}>`}
		<${Panel} title="Size">
			<${Select} label="Aspect ratio" value=${a.aspect} options=${ASPECTS} onChange=${(v) => onAttrs({ aspect: v })} />
			${a.aspect === 'fixed' &&
			html`<div class="wpse-control">
				<label class="wpse-label" for=${name + '-h'}>Height</label>
				<div class="wpse-range">
					<input type="range" min="240" max="1000" step="10" value=${a.height} aria-label="Height" onInput=${(e) => onAttrs({ height: Number(e.currentTarget.value) })} />
					<span class="wpse-unit"><input id=${name + '-h'} type="number" min="240" max="1000" value=${a.height} onChange=${(e) => onAttrs({ height: Math.max(240, Math.min(1000, Number(e.currentTarget.value) || 480)) })} /> px</span>
				</div>
			</div>`}
			<div class="wpse-control">
				<span class="wpse-label">Width</span>
				<div class="wpse-btngroup" role="group" aria-label="Width">
					${WIDTHS.map((w) => html`<button key=${w} type="button" class=${cx(a.width === w && 'is-pressed')} aria-pressed=${a.width === w} onClick=${() => onAttrs({ width: w })}>${w}%</button>`)}
				</div>
			</div>
		</${Panel}>
		<${Panel} title="Viewer">
			<${Select}
				label="Customizer"
				value=${current ? a.customizer : 'hide'}
				options=${[['product', 'Use the product setting'], ['show', 'Show'], ['hide', 'Hide']]}
				disabled=${!current}
				onChange=${(v) => onAttrs({ customizer: v })}
				help=${current ? (settings ? `Product setting: ${settings.customizerEnabled ? 'on' : 'off'}.` : '') : 'The customizer needs the product’s add-to-cart form, so it is available for the current product only.'}
			/>
			<${Toggle}
				label="Use the global toolbar settings"
				checked=${!a.controls}
				onChange=${(on) => onAttrs({ controls: on ? null : { ...(settings?.controls || { zoom: false, reset: false, autorotate: false, download: true, gallery: true }) } })}
			/>
			${a.controls && CONTROL_KEYS.map(([k, label]) => html`<${Toggle} key=${k} label=${label} checked=${!!a.controls[k]} onChange=${(v) => onAttrs({ controls: { ...a.controls, [k]: v } })} />`)}
		</${Panel}>
		<${Panel} title="Background">
			<${Select} label="Background" value=${a.background} options=${[['product', 'Product setting'], ['transparent', 'Transparent'], ['color', 'Color']]} onChange=${(v) => onAttrs({ background: v })} />
			${a.background === 'color' &&
			html`<div class="wpse-control wpse-color">
				<input type="color" aria-label="Background color" value=${a.backgroundColor} onInput=${(e) => onAttrs({ backgroundColor: e.currentTarget.value })} />
				<code>${a.backgroundColor}</code>
			</div>`}
		</${Panel}>
		<${Panel} title="Advanced" open=${false}>
			<div class="wpse-control">
				<label class="wpse-label" for=${name + '-cls'}>Additional CSS class(es)</label>
				<input id=${name + '-cls'} class="wpse-input" type="text" value=${a.className} onChange=${(e) => onAttrs({ className: e.currentTarget.value.trim() })} />
				<p class="wpse-help">Separate multiple classes with spaces.</p>
			</div>
			<div class="wpse-control">
				<span class="wpse-label">Shortcode</span>
				<code class="wpse-code">${sc}</code>
				<button type="button" class="wpse-link" onClick=${copy}>${copied ? 'Copied!' : 'Copy'}</button>
				<p class="wpse-help">The same viewer anywhere shortcodes work.</p>
			</div>
		</${Panel}>
	`;
}
